// Interop with the format spec and the fixtures generated by an independent
// Python implementation (copied from byplay-previs-app/docs/fixtures by `npm run sync`).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { renderFileName, renderFolder } from '../src/naming';
import { base45Decode, base45Encode } from '../src/qr/base45';
import { qrMatrix } from '../src/qr/matrix';
import {
  QR_MAX_CHARS,
  QR_MAX_PARTS,
  QrTooLargeError,
  decodeQrPayloads,
  encodeProfileQr,
  isQrAlphanumeric,
  profileToQrData,
  splitQrData,
} from '../src/qr/payload';
import { DEFAULT_NAMING, ProductionProfileSchema } from '../src/schema';

const fixture = (name: string) => readFileSync(join(__dirname, 'fixtures', name), 'utf8');
const exampleJson = JSON.parse(fixture('example.bpprod'));
// One payload per line. Only line breaks are stripped: space is a base45 character.
const lines = (text: string) => text.split(/\r?\n/).filter((l) => l !== '');

describe('example.bpprod', () => {
  it('parses with the schema, unchanged', () => {
    const r = ProductionProfileSchema.safeParse(exampleJson);
    expect(r.success).toBe(true);
    expect(r.data).toEqual(exampleJson);
  });
});

describe('QR fixtures from the Python implementation', () => {
  it('decodes the single code', () => {
    const payloads = lines(fixture('example.qr-single.txt'));
    expect(payloads).toHaveLength(1);
    expect(payloads[0].startsWith('BPP1:')).toBe(true);
    expect(decodeQrPayloads(payloads)).toEqual(exampleJson);
  });

  it('decodes the parts, in either order', () => {
    const payloads = lines(fixture('example.qr-parts.txt'));
    expect(payloads).toHaveLength(2);
    expect(decodeQrPayloads(payloads)).toEqual(exampleJson);
    expect(decodeQrPayloads([...payloads].reverse())).toEqual(exampleJson);
  });

  it('fixture payloads are all QR alphanumeric', () => {
    for (const p of [...lines(fixture('example.qr-single.txt')), ...lines(fixture('example.qr-parts.txt'))]) {
      expect(isQrAlphanumeric(p)).toBe(true);
    }
  });
});

describe('our encoder', () => {
  it('round-trips the example as one code', () => {
    const payloads = encodeProfileQr(exampleJson, { maxChars: 5000 });
    expect(payloads).toHaveLength(1);
    expect(payloads[0].startsWith('BPP1:')).toBe(true);
    expect(decodeQrPayloads(payloads)).toEqual(exampleJson);
  });

  it('round-trips the example as parts within the size limit', () => {
    const payloads = encodeProfileQr(exampleJson);
    expect(payloads.length).toBeGreaterThan(1);
    const tag = payloads[0].split('/')[2].slice(0, 4);
    payloads.forEach((p, i) => {
      expect(p.startsWith(`BPP1P:${i + 1}/${payloads.length}/${tag}:`)).toBe(true);
      expect(p.length).toBeLessThanOrEqual(QR_MAX_CHARS);
    });
    expect(tag).toMatch(/^[0-9A-Z]{4}$/);
    expect(decodeQrPayloads(payloads)).toEqual(exampleJson);
    expect(decodeQrPayloads([...payloads].reverse())).toEqual(exampleJson);
  });

  it('can force several parts and still decode', () => {
    for (let n = 2; n <= QR_MAX_PARTS; n++) {
      const payloads = encodeProfileQr(exampleJson, { minParts: n });
      expect(payloads).toHaveLength(n);
      expect(decodeQrPayloads(payloads)).toEqual(exampleJson);
    }
  });

  it('keeps spaces at chunk edges (space is a base45 character)', () => {
    const data = profileToQrData(exampleJson);
    const spaceAt = data.indexOf(' ', 10);
    expect(spaceAt).toBeGreaterThan(0);
    // Force a split right after a space so a chunk ends with one.
    const parts = [`BPP1P:1/2/TEST:${data.slice(0, spaceAt + 1)}`, `BPP1P:2/2/TEST:${data.slice(spaceAt + 1)}`];
    expect(parts[0].endsWith(' ')).toBe(true);
    expect(decodeQrPayloads(parts)).toEqual(exampleJson);
  });

  it('only emits QR alphanumeric characters', () => {
    for (const p of [...encodeProfileQr(exampleJson), ...encodeProfileQr(exampleJson, { maxChars: 5000 })]) {
      expect(isQrAlphanumeric(p)).toBe(true);
    }
  });

  it('refuses data that needs more than 16 codes', () => {
    const data = 'A'.repeat(QR_MAX_PARTS * QR_MAX_CHARS);
    expect(() => splitQrData(data)).toThrow(QrTooLargeError);
  });

  it('builds QR matrices in alphanumeric mode at EC level M, version 20 or below', () => {
    for (const p of encodeProfileQr(exampleJson)) {
      const m = qrMatrix(p);
      expect(m.version).toBeLessThanOrEqual(20);
      expect(m.size).toBe(17 + 4 * m.version);
    }
  });

  it('uses the zlib wrapper, as the Python side expects', () => {
    const bytes = base45Decode(profileToQrData(exampleJson));
    // RFC 1950 header: CMF 0x78, and (CMF*256 + FLG) % 31 === 0.
    expect(bytes[0]).toBe(0x78);
    expect((bytes[0] * 256 + bytes[1]) % 31).toBe(0);
  });
});

describe('base45 (RFC 9285 examples)', () => {
  const enc = (s: string) => base45Encode(new TextEncoder().encode(s));
  const dec = (s: string) => new TextDecoder().decode(base45Decode(s));
  it('encodes', () => {
    expect(enc('AB')).toBe('BB8');
    expect(enc('Hello!!')).toBe('%69 VD92EX0');
    expect(enc('base-45')).toBe('UJCLQE7W581');
    expect(enc('ietf!')).toBe('QED8WEX0');
  });
  it('decodes and rejects bad input', () => {
    expect(dec('QED8WEX0')).toBe('ietf!');
    expect(() => base45Decode('GGW')).toThrow();
    expect(() => base45Decode('ZZZZ')).toThrow();
    expect(() => base45Decode('ab')).toThrow();
  });
});

describe('templates (spec example)', () => {
  const values = { project: 'ABC', day: 1, roll: 1, scene: 'D12', take: 1 };
  const date = new Date(2026, 9, 7, 16, 43);
  const naming = exampleJson.naming.snapshot;

  it('renders the folder and file from the spec', () => {
    expect(renderFolder(naming.folder, values, date).join('/')).toBe('ABC/Day_01');
    expect(renderFileName(naming.file, values, date)).toBe('ABC_Day-01_20261007_1643_R01_D12_Tk1');
  });

  it('renders the default naming the same way', () => {
    expect(renderFileName(DEFAULT_NAMING.snapshot.file, values, date)).toBe(
      'ABC_Day-01_20261007_1643_R01_D12_Tk1',
    );
  });

  it('cuts long names at 150 code points and drops what the cut leaves dangling', () => {
    const long = `${'a'.repeat(148)}_b_${'c'.repeat(20)}`;
    expect(renderFileName(long, {}, date)).toBe(`${'a'.repeat(148)}_b`);
    const dangling = `${'a'.repeat(149)}_${'c'.repeat(20)}`;
    expect(renderFileName(dangling, {}, date)).toBe('a'.repeat(149));
    const emoji = `${'a'.repeat(149)}🎬🎬`;
    expect(renderFileName(emoji, {}, date)).toBe(`${'a'.repeat(149)}🎬`);
  });

  it('drops R{roll:02} entirely when roll is empty', () => {
    expect(renderFileName(naming.file, { ...values, roll: '' }, date)).toBe('ABC_Day-01_20261007_1643_D12_Tk1');
    expect(renderFileName(naming.file, { ...values, roll: undefined }, date)).toBe(
      'ABC_Day-01_20261007_1643_D12_Tk1',
    );
  });
});
